from pathlib import Path
import sys,json,hashlib
D=Path(__file__).resolve().parent;S=Path(sys.argv[1]);s=S.read_text();helpers=s[s.index('/* ------------------------------------------------------------------ helpers */'):s.index('/* ================================================================== 1 cube')];a=s.index("reg('crossword', {");b=s.index('/* ================================================================== 18 wordSearch',a);fragment=s[a:b];a=fragment.index('  render(env) {')+len('  render(env) {');body=fragment[a:fragment.rindex('  },\n});')]
rules=[('const cell = Math.min(W * (0.88 - clueW) / C, H * (below ? 0.64 : 0.8) / R, u * 0.14);','const nativeCell = Math.min(W * (0.88 - clueW) / C, H * (below ? 0.64 : 0.8) / R, u * 0.14);\n    const cell=nativeCell*0.58;'),('const fsC = Math.max(smallSize(env) * 1.15, cell * 0.24);','const fsC = Math.max(smallSize(env) * 1.15, nativeCell * 0.24);'),('const gx = (W - gw - (clueW ? W * clueW : 0)) / 2, gy = (H - gh - (below ? fsC * 5 : 0)) / 2;','const gx=(W-gw)/2, gy=(H-gh-fsC*5)/2;'),("size: cell * 0.2, align: 'left'","size: nativeCell*.2, align: 'left'"),('const x = gx + (c0[wi] + j + 0.5) * cell, y = gy + (rowsW[wi] + 0.56) * cell;','const x = gx + (c0[wi] + j + 0.5) * cell, y = gy + (rowsW[wi] + .64) * cell;'),('size: cell * 0.7, x, y','size: cell * .65, x, y'),('const cxl = below ? gx : gx + gw + W * 0.035, cyl = below ? gy + gh + fs * 1.6 : gy + fs;','const cxl = true ? gx : gx + gw + W * 0.035, cyl = true ? gy + gh + fs * 1.6 : gy + fs;'),('const yy = below ? cyl + (i % 2) * fs * 1.7 : cyl + i * fs * 1.9 + (i >= 2 ? fs * 0.8 : 0), xx = below && i >= 2 ? cxl + gw * 0.55 : cxl;','const yy = true ? cyl + (i % 2) * fs * 1.7 : cyl + i * fs * 1.9 + (i >= 2 ? fs * 0.8 : 0), xx = true && i >= 2 ? cxl + gw * 0.55 : cxl;')]
for old,new in rules:
 assert body.count(old)==1,old
 body=body.replace(old,new)
