(D/'boundary.json').write_text(json.dumps({'source':S.name,'sourceSHA256':hashlib.sha256(S.read_bytes()).hexdigest(),'rules':rules,'renderSHA256':hashlib.sha256(body.encode()).hexdigest(),'sourceOnly':True,'qualified':False,'scope':'approved58A input-independent semantic family only; no fixed text/seed/delta, geometry/font/Canvas/owner/placement/UI authority'},indent=2)+'\n')
